{
  "story": "K-means groups points by iteratively assigning each point to the nearest centroid and then recomputing the centroid locations until assignments stabilize.",
  "aha": {
    "stateId": "assign",
    "observation": "Points switch cluster membership dynamically as the boundary moves."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Algorithm Step",
      "options": [
        "Init",
        "Assign",
        "Update",
        "Converge"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "K-Means Iteration",
        "regions": [
          {
            "id": "centroids",
            "label": "Centroids",
            "values": ["C1: (2,2)", "C2: (8,8)"]
          },
          {
            "id": "points",
            "label": "Data Points",
            "values": ["P1: (1,1)", "P2: (2,3)", "P3: (7,9)", "P4: (9,8)"]
          }
        ],
        "states": [
          {
            "id": "init",
            "label": "Initialize",
            "short": "Init",
            "sentence": "Place initial centroids randomly in the space.",
            "why": "Starting positions anchor the first distance computation.",
            "active": ["centroids"],
            "calloutRegion": "centroids",
            "readouts": [
              {
                "id": "iter",
                "label": "Iteration",
                "value": "0"
              }
            ]
          },
          {
            "id": "assign",
            "label": "Assign Points",
            "short": "Assign",
            "sentence": "Assign each point to the nearest centroid.",
            "why": "Minimizes within-cluster variance for current centers.",
            "active": ["points"],
            "calloutRegion": "points",
            "readouts": [
              {
                "id": "iter",
                "label": "Iteration",
                "value": "1"
              }
            ]
          },
          {
            "id": "update",
            "label": "Update Centroids",
            "short": "Update",
            "sentence": "Recalculate centroids as the mean of assigned points.",
            "why": "Shifts centers to the true geometric average.",
            "active": ["centroids"],
            "calloutRegion": "centroids",
            "readouts": [
              {
                "id": "iter",
                "label": "Iteration",
                "value": "1"
              }
            ]
          },
          {
            "id": "converge",
            "label": "Check Convergence",
            "short": "Converge",
            "sentence": "Repeat until no points change their cluster assignment.",
            "why": "Stops computation when a stable optimum is reached.",
            "active": ["points", "centroids"],
            "calloutRegion": "points",
            "readouts": [
              {
                "id": "iter",
                "label": "Iteration",
                "value": "2"
              }
            ]
          }
        ]
      }
    ]
  }
}
